exec('import csv,os,requests\nrows=list(csv.DictReader(open("signals_history.csv",encoding="utf-8")))\nlatest=max(r["date"] for r in rows)\nselected=[r for r in rows if r["date"]==latest and r["signal"] in ("ACHAT","SURCHAUFFE")]\nlines=["INVESTMENT ASSISTANT",f"Date : {latest}",""]\nfor r in selected: lines.append(("ACHAT" if r["signal"]=="ACHAT" else "SURCHAUFFE")+" | "+r["ticker"]+" | Score "+r["score"]+"/100 | Var5j "+r["var5"]+"% | RSI "+r["rsi14"]+" | RVOL "+r["rvol"])\nif not selected: lines.append("Aucun signal ACHAT ou SURCHAUFFE aujourd hui.")\nlines.extend(["","Signaux experimentaux en paper trading. Aucun ordre reel."])\nmessage="\\n".join(lines)\nr=requests.post("https://api.telegram.org/bot"+os.environ["TELEGRAM_BOT_TOKEN"]+"/sendMessage",data={"chat_id":os.environ["TELEGRAM_CHAT_ID"],"text":message},timeout=30)\nprint("Telegram alert:",r.status_code,r.json().get("ok"))')
